(function () {
  'use strict';
  var state = { openingTactic: 'breakthrough', tab: 'front', fleetId: '', fleets: [], frontier: null, frontierScope: '', missions: null, siegeContext: null, training:false, busy: false, request: 0 };
  var root, body, status, previousFocus, renderBody=null, displayedLang;
  var missionIds = ['first_sortie', 'secure_node', 'move_yield', 'restore_fleet', 'hold_front'];
  var missionLabels = [['착륙 방어','Landing defense'],['광산 확보','Secure the mine'],['화물 호위','Escort the yield'],['전력 복구','Restore the fleet'],['전선 개방','Hold the front']];
  function missionContext() { return !state.siegeContext&&state.missions&&(state.missions.missions||[]).find(function(m){return m.status==='active'||m.status==='completed';}); }
  function activeMission() { return !state.siegeContext&&state.missions && (state.missions.missions||[]).find(function(m){return m.status==='active';}); }
  async function operationAction(missionId, actionName, path, data) { var m=activeMission(); return m&&m.id===missionId ? api('/starter-ops/'+missionId+'/action',Object.assign({action:actionName},data)) : api(path,data); }
  var titles = {front:['전선','Front'],fleet:['함대','Fleet'],missions:['임무','Missions'],base:['기지','Base']};
  function setBody(renderer) { renderBody=renderer;body.innerHTML=siegePreparationBrief()+renderer();displayedLang=typeof LANG==='undefined'?'en':LANG; }
  window.refreshCommandCenterLocale=function(){
    var chat=document.getElementById('chatOverlay'),chatButton=document.getElementById('chatToggleBtn');
    if(chatButton){var expanded=chat&&!chat.classList.contains('collapsed');chatButton.setAttribute('aria-label',L(expanded?'통신 닫기':'통신 열기',expanded?'Close communications':'Open communications'));}
    if(!root)return;
    document.querySelectorAll('[data-command-nav]').forEach(function(b){var label=b.querySelector('[data-command-label]')||b.querySelector('span:not([data-game-icon])');if(label)label.textContent=L.apply(null,titles[b.dataset.commandNav]);});
    root.querySelector('h2').textContent=L.apply(null,titles[state.tab]);
    var mapButton=root.querySelector('[data-cc="close"]');if(mapButton){mapButton.setAttribute('aria-label',L('영토 지도 보기','View territory map'));mapButton.title=L('영토 지도 보기','View territory map');}
    root.querySelector('[data-cc="refresh"]').setAttribute('aria-label',L('새로고침','Refresh'));
    if(root.hidden||state.busy||!renderBody)return;
    var values=Array.from(body.querySelectorAll('input,select,textarea')).map(function(el){return {id:el.id,value:el.value,checked:el.checked};});
    var focus=document.activeElement,focusId=focus&&focus.id,action=focus&&focus.dataset&&focus.dataset.cc,actionId=focus&&focus.dataset&&focus.dataset.id,scroll=body.scrollTop;
    if(typeof gameUiRelocalize==='function')status.textContent=gameUiRelocalize(status.textContent,displayedLang);
    setBody(renderBody);
    values.forEach(function(v){var el=v.id&&document.getElementById(v.id);if(el&&v.id!=='ccLanguage'){el.value=v.value;if('checked' in el)el.checked=v.checked;}});
    body.scrollTop=scroll;
    var next=focusId&&document.getElementById(focusId);if(!next&&action)next=Array.from(body.querySelectorAll('[data-cc]')).find(function(el){return el.dataset.cc===action&&el.dataset.id===actionId;});
    if(next&&body.contains(next))next.focus({preventScroll:true});
  };
  function ko() { return typeof LANG !== 'undefined' && LANG === 'ko'; }
  function L(k,e) { return typeof gameUiText==='function' ? gameUiText(e,k) : ko() ? k : e; }
  function esc(v) { return String(v == null ? '' : v).replace(/[&<>"']/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c];}); }
  function n(v) { return Number.isFinite(Number(v)) ? Number(v).toLocaleString(typeof gameLocale==='function'?gameLocale():undefined) : '0'; }
  function icon(name,size) { return window.GameIcons?window.GameIcons.render(name,{size:size||18}):''; }
  var actionIcons = {close:'close',refresh:'refresh',login:'profile',faction:'guild',attack:'attack',defense:'defense',collect:'claim',cargo:'transport','cancel-cargo':'close','check-cargo':'timer','front-scope':'resources','withdraw-stock':'resources','raid-cargo':'attack','claim-mission':'gift','start-mission':'missions','mission-action':'arrow','operation-repair':'repair','inspect-fleet':'check','repair-quote':'repair','legacy-fleet':'formation',cards:'fitting',collection:'collection',gacha:'cargo','battle-hub':'attack',objectives:'objective',practice:'target',guide:'info',story:'story','legacy-base':'base',land:'territory','claim-land':'claim',battle:'attack','fleet-detail':'repair','select-fleet':'fleet'};
  function button(label,action,id,extra) { return '<button type="button" class="cc-button '+(extra||'')+'" data-cc="'+action+'"'+(id!=null?' data-id="'+esc(id)+'"':'')+'>'+icon(action==='tab'?id:actionIcons[action]||'arrow')+'<span>'+esc(label)+'</span></button>'; }
  function siegeContext(value) {
    var wallet=String(window.walletState&&window.walletState.address||'').toLowerCase();
    if(!value||value.kind!=='siege'||!Number.isSafeInteger(Number(value.siegeId))||Number(value.siegeId)<1||!wallet||String(value.wallet||'').toLowerCase()!==wallet||!/^[-a-z0-9_]{1,64}$/i.test(value.sectorCode||''))return null;
    return {kind:'siege',siegeId:Number(value.siegeId),sectorCode:value.sectorCode,battleId:Number(value.battleId)||null,
      ownFleetId:Number(value.ownFleetId)||null,wallet:wallet,intent:value.intent==='repair'?'repair':'supply',supplyAffectsSiege:false};
  }
  function siegePreparationBrief() {
    var c=state.siegeContext;if(!c)return '';
    var f=state.frontier,selected=state.fleets.find(function(x){return String(x.id)===state.fleetId;});
    var title=tl('Shared siege preparation','공동 공성 준비','共同攻城戦の準備','共同攻城准备','Persiapan pengepungan bersama','Chuẩn bị công thành chung','เตรียมการล้อมร่วม');
    var route=tl('Collect production → deliver cargo → repair depot → repair your fleet → return to siege.','생산품 수령 → 화물 도착 → 정비 창고 → 내 함대 수리 → 공성 복귀.','生産物回収 → 貨物到着 → 整備倉庫 → 自艦隊修理 → 攻城戦へ。','收取产出 → 货物到达 → 维修仓库 → 修理自己的舰队 → 返回攻城。','Ambil produksi → kirim kargo → depot perbaikan → perbaiki armada sendiri → kembali ke pengepungan.','Thu sản lượng → giao hàng → kho sửa chữa → sửa hạm đội của bạn → trở lại công thành.','รับผลผลิต → ส่งสินค้า → คลังซ่อม → ซ่อมกองยานของคุณ → กลับสู่การล้อม');
    var noBuff=tl('Supplies repair surviving ships; they do not grant a siege combat buff. Rebuild lost hulls from your collection.','보급은 생존 함선의 HP 수리에 쓰이며 공성 전투 버프를 주지 않습니다. 격침 함체는 도감에서 재건하세요.','補給は生存艦のHP修理に使用し、攻城戦バフは付与しません。沈没船体は図鑑で再建してください。','补给用于修复幸存舰船的HP，不提供攻城战增益。被击沉舰体须从图鉴重建。','Pasokan memperbaiki HP kapal yang selamat, tanpa buff tempur pengepungan. Bangun ulang lambung hancur dari koleksi.','Tiếp tế sửa HP tàu sống sót, không tăng sức chiến đấu công thành. Tái tạo thân tàu đã mất từ bộ sưu tập.','เสบียงใช้ซ่อม HP เรือที่รอด ไม่ให้บัฟการรบล้อม สร้างตัวเรือที่สูญเสียใหม่จากคอลเลกชัน');
    var fleetLabel=tl('My selected fleet','내 선택 함대','選択中の自艦隊','我选择的舰队','Armada saya yang dipilih','Hạm đội tôi đã chọn','กองยานที่ฉันเลือก');
    var fleetHint=selected?esc(selected.name)+' · HP '+n(selected.total_hp)+' / '+n(selected.total_max_hp):tl('Select an owned fleet below. New commanders can get one in the first operation.','아래에서 자기 함대를 선택하세요. 신규 지휘관은 첫 작전에서 함대를 받을 수 있습니다.','下で自分の艦隊を選択。新人は最初の作戦で入手できます。','在下方选择自己的舰队，新指挥官可在首次行动领取。','Pilih armada milikmu di bawah. Komandan baru mendapat armada di operasi pertama.','Chọn hạm đội của bạn bên dưới. Chỉ huy mới nhận hạm đội ở chiến dịch đầu.','เลือกกองยานของคุณด้านล่าง ผู้บัญชาการใหม่รับกองยานได้ในปฏิบัติการแรก');
    var html='<section class="cc-card selected" data-siege-context="'+c.siegeId+'" data-supply-affects-siege="false"><h3>'+esc(title)+' #'+c.siegeId+' · '+esc(c.sectorCode.toUpperCase())+'</h3><p>'+esc(route)+'</p><p class="cc-meta">'+esc(noBuff)+'</p><p>'+esc(fleetLabel)+': <span id="ccSiegeFleetName">'+fleetHint+'</span></p>';
    if(f){
      var shared=f.scope==='guild';
      html+='<p class="cc-meta">'+esc(shared?tl('Using the shared guild depot. Normal members can deliver and repair their own surviving ships.','길드 공동 창고를 사용합니다. 일반 길드원도 운송하고 자기 생존 함선을 수리할 수 있습니다.','ギルド共有倉庫を使用。一般メンバーも輸送・自分の生存艦の修理が可能です。','使用公会共享仓库，普通成员也可运输并修理自己的幸存舰船。','Menggunakan depot guild bersama. Anggota biasa dapat mengirim dan memperbaiki kapal sendiri yang selamat.','Đang dùng kho bang hội chung. Thành viên thường có thể giao hàng và sửa tàu sống sót của mình.','กำลังใช้คลังสมาคมร่วม สมาชิกทั่วไปส่งสินค้าและซ่อมเรือของตนที่รอดได้'):tl('Using your personal depot. Join a guild to share supplies; personal and guild stock stay separate.','개인 창고를 사용합니다. 공동 보급에는 길드 가입이 필요하며 개인/길드 재고는 분리됩니다.','個人倉庫を使用。共同補給にはギルド参加が必要で、在庫は別管理です。','使用个人仓库，共同补给需要加入公会；个人与公会库存分开。','Menggunakan depot pribadi. Gabung guild untuk pasokan bersama; stok pribadi dan guild terpisah.','Đang dùng kho cá nhân. Vào bang hội để tiếp tế chung; kho cá nhân và bang hội tách biệt.','กำลังใช้คลังส่วนตัว เข้าสมาคมเพื่อแบ่งปันเสบียง สต็อกส่วนตัวและสมาคมแยกกัน'))+'</p>';
      var progress=(f.contributions||[]).find(function(x){return String(x.wallet||'').toLowerCase()===c.wallet;});
      if(progress)html+='<p class="cc-meta">'+esc(tl('My contribution today: produced / delivered / HP repaired','오늘 내 기여: 생산 / 운송 / 수리 HP','本日の貢献：生産／配送／修理HP','今日我的贡献：生产／运输／修复HP','Kontribusi saya hari ini: produksi / kirim / HP diperbaiki','Đóng góp hôm nay: sản xuất / giao / HP đã sửa','ผลงานวันนี้: ผลิต / ส่ง / HP ที่ซ่อม'))+': '+n(progress.produced)+' / '+n(progress.delivered)+' / '+n(progress.repaired)+'</p>';
    }
    return html+'<div class="cc-actions">'+button(tl('Supply and cargo','보급·운송','補給・輸送','补给与运输','Pasokan dan kargo','Tiếp tế và vận tải','เสบียงและสินค้า'),'siege-supply')+button(tl('Repair my fleet','내 함대 수리','自艦隊を修理','修理我的舰队','Perbaiki armada saya','Sửa hạm đội của tôi','ซ่อมกองยานของฉัน'),'siege-repair')+button(tl('Return to siege','공성으로 돌아가기','攻城戦へ戻る','返回攻城','Kembali ke pengepungan','Trở lại công thành','กลับสู่การล้อม'),'siege-return')+'</div></section>';
  }
  function toast(message,error) { status.textContent=message; status.classList.toggle('error',!!error); }
  async function api(path,data) {
    if(state.siegeContext&&String(window.walletState&&window.walletState.address||'').toLowerCase()!==state.siegeContext.wallet)throw Error('INVALID_TOKEN');
    if(path.indexOf('/frontier/')===0&&state.frontierScope==='personal'){if(data===undefined)path+=(path.indexOf('?')<0?'?':'&')+'scope=personal';else data=Object.assign({},data,{scope:'personal'});}
    var requestAtStart=state.request,tokenAtStart=localStorage.getItem('pw_token');var headers=typeof getAuthHeaders==='function'?getAuthHeaders():{};
    headers['Content-Type']='application/json';
    var r=await fetch('/api'+path,{method:data===undefined?'GET':'POST',headers:headers,cache:'no-store',body:data===undefined?undefined:JSON.stringify(data)});
    var json=await r.json(); if(data!==undefined&&(state.request!==requestAtStart||localStorage.getItem('pw_token')!==tokenAtStart))throw Error('STALE_REQUEST');if(!r.ok||json.error)throw Error(json.error||'REQUEST_FAILED');return json;
  }
  function errorText(e) {
    var map={UNAUTHORIZED:['로그인 후 다시 열어주세요.','Sign in and reopen this screen.'],INVALID_TOKEN:['로그인이 만료되었습니다. 다시 로그인해주세요.','Your session expired. Please sign in again.'],FLEET_IN_BATTLE:['이미 전투 중인 함대입니다. 전투 보기로 돌아가세요.','This fleet is already fighting. Resume its battle.'],FLEET_TRANSPORTING:['운송 중인 함대입니다. 도착 후 다시 출격할 수 있습니다.','This fleet is transporting cargo until arrival.'],FLEET_MINING:['자원 출항 중인 함대입니다.','This fleet is mining.'],FLEET_EMPTY:['출격 가능한 함선이 없습니다. 임무에서 시작 함대를 받으세요.','No deployable ships. Start the first mission for a fleet.'],PRODUCTION_NOT_READY:['생산 중입니다. 다음 생산 시각 이후 다시 확인하세요.','Production is not ready yet.'],INSUFFICIENT_STOCK:['창고 재료가 부족합니다. 생산품을 수령·운송하세요.','Not enough depot materials. Collect and deliver production.'],INSUFFICIENT_GP:['수리에 필요한 GP가 부족합니다.','Not enough GP for this repair.'],NODE_PROTECTED:['점령 보호 시간입니다. 다른 거점을 공략하세요.','This node is protected. Choose another target.'],DAILY_ATTACK_LIMIT:['오늘의 출격 한도에 도달했습니다.','Daily attack limit reached.'],PREVIOUS_MISSION_REQUIRED:['앞선 임무를 완료하고 보상을 수령하세요.','Complete and claim the previous mission first.'],CARGO_NOT_ARRIVED:['화물이 아직 도착하지 않았습니다. 도착 시각을 확인하세요.','Cargo has not arrived yet. Check its arrival time.'],REPAIR_QUOTE_CHANGED:['정비 비용이 변경되었습니다. 새 견적을 확인하세요.','Repair cost changed. Review the updated quote.'],STARTER_FLEET_REQUIRED:['이 임무는 전초 작전 함대를 선택해야 합니다.','Select your starter operation fleet for this mission.'],MISSION_NOT_READY:['앞선 임무를 완료하고 보상을 수령하세요.','Complete and claim the previous mission first.']};
    map.CARGO_DELIVERY_REQUIRED=['광산 재료를 먼저 정비 창고로 운송하세요. 도착한 재료를 제작에 사용할 수 있습니다.','Deliver mine materials to the repair depot before using them for crafting.'];
    map.GUILD_WITHDRAW_ROLE_REQUIRED=['개인 인출은 길드장·간부만 가능합니다. 공동 수리·운송은 이용할 수 있습니다.','Only guild leaders and officers can withdraw to personal inventory. Shared repair and transport remain available.'];map.REPAIR_REQUIRED=['손상 함선을 먼저 수리해주세요.','Repair damaged ships first.'];map.FACTION_REQUIRED=['먼저 진영을 선택해주세요. 기지 관리의 프로필에서 선택할 수 있습니다.','Choose a faction first from your base profile.'];var pair=map[e.message];return pair?L(pair[0],pair[1]):L('요청을 완료하지 못했습니다. 상태를 새로고침하세요. ','Could not complete the request. Refresh the state. ')+e.message;
  }
  function fleetSelect() {
    return '<div class="cc-field"><label for="ccFleetSelect">'+L('출격·운송 함대','Fleet for sortie / cargo')+'</label><select id="ccFleetSelect"><option value="">'+L('함대 선택','Select a fleet')+'</option>'+state.fleets.map(function(f){return '<option value="'+esc(f.id)+'"'+(String(f.id)===state.fleetId?' selected':'')+'>'+esc(f.name)+' · '+n(f.ships_alive)+L('척',' ships')+(f.is_in_battle?' · '+L('전투 중','In battle'):'')+'</option>';}).join('')+'</select></div>';
  }
  function selectedFleet() { var id=state.fleetId;if(!id)throw Error(L('함대를 먼저 선택해주세요.','Select a fleet first.'));return id; }
  function time(value) { var d=new Date(value);return Number.isFinite(d.getTime())?d.toLocaleTimeString(typeof gameLocale==='function'?gameLocale():ko()?'ko-KR':'en-US',{hour:'2-digit',minute:'2-digit'}):'—'; }
  function role(code) { return ({dps:L('화력','Firepower'),tackle:L('요격','Interceptor'),tank:L('방어','Tank'),logi:L('수리 지원','Repair support'),ewar:L('전자전','Electronic warfare'),sniper:L('저격','Sniper'),bomber:L('폭격','Bomber')})[code]||code; }
  function resource(code) { return ({iron_dust:L('철 분말','Iron dust'),hull_plate:L('함체 판재','Hull plate')})[code]||code; }
  function cargoCapacity() { return state.training?100:Math.max(1,Number(state.frontier&&state.frontier.cargoCapacity)||100); }
  function batchCap() { return Number(state.frontier&&state.frontier.balance&&state.frontier.balance.batchCap)||4; }
  function copy(k,e,values) { return L(k,e).replace(/\{(\w+)\}/g,function(_,key){return values[key]==null?'':n(values[key]);}); }
  function cargoMinutes() {var active=activeMission();if(state.training&&active?.id==='move_yield')return 1;return state.frontier.nodes.some(function(x){return x.node_type==='logistics'&&x.owner_key===state.frontier.ownerKey;})?9:10;}
  function fleetName(id) {var fleet=state.fleets.find(function(f){return String(f.id)===String(id);});return fleet?fleet.name:L('함대 #','Fleet #')+id;}
  function nodeMeta(type) { return ({resource:[L('자원 거점','Resource node'),icon('resources',26),copy('30분마다 철 분말 20 · 함체 판재 4. 최대 {batches}회분({hours}시간)을 저장합니다.','20 iron dust + 4 hull plates every 30 minutes. Storage holds {batches} batches ({hours} hours).',{batches:batchCap(),hours:batchCap()*(Number(state.frontier.balance&&state.frontier.balance.batchMinutes)||30)/60})],logistics:[L('물류 거점','Logistics node'),icon('transport',26),L('점령하면 운송 시간이 10분에서 9분으로 줄고, 한 번에 100개 대신 200개를 운송합니다.','Control reduces delivery from 10 to 9 minutes and raises shipment capacity from 100 to 200.')],repair:[L('정비 거점','Repair node'),icon('repair',26),L('도착한 철 분말과 GP로 실제 함선을 수리합니다. 점령 혜택은 하루 한도 안에서 적용됩니다.','Delivered iron dust and GP repair your ships. Control grants a capped daily material discount.')]})[type]; }
  function openingBrief() {
    var text=tl('Choose your opening · 10 seconds, then tactical AI resumes.', '첫 10초 전술을 선택하세요. 이후 전술 AI가 이어받습니다.', '最初の10秒の戦術を選択。その後は戦術AIが再開します。', '选择开场10秒战术，随后战术AI接管。', 'Pilih taktik pembuka 10 detik, lalu AI taktis melanjutkan.', 'Chọn chiến thuật mở đầu 10 giây, sau đó AI tiếp tục.', 'เลือกยุทธวิธี 10 วินาทีแรก จากนั้น AI จะควบคุมต่อ');
    var options=[['breakthrough',tl('Breakthrough · wedge + advance','돌파 · 쐐기 + 전진','突破 · 楔形＋前進','突破 · 楔形＋前进','Terobos · baji + maju','Đột phá · nêm + tiến','บุกทะลวง · ลิ่ม + เดินหน้า')],['flank',tl('Flanking screen · screen + flank','측면 차단 · 스크린 + 측면 기동','側面遮断 · スクリーン＋側面機動','侧翼掩护 · 屏障＋侧翼机动','Layar sayap · layar + mengepung','Chắn sườn · màn chắn + đánh sườn','คุ้มกันปีก · แนวคุ้มกัน + โอบข้าง')]];
    return '<div class="cc-field"><label for="ccOpeningTactic">'+esc(text)+'</label><select id="ccOpeningTactic">'+options.map(function(x){return '<option value="'+x[0]+'"'+(state.openingTactic===x[0]?' selected':'')+'>'+esc(x[1])+'</option>';}).join('')+'</select></div><p class="cc-meta">'+tl('Advance closes directly; flank approaches sideways with a screen formation. Hull stats and rewards stay the same.','전진은 정면 접근, 측면 기동은 스크린 진형으로 옆을 공략합니다. 함체 능력치와 보상은 같습니다.','前進は正面へ、側面機動はスクリーンで横から接近。船体性能と報酬は同じです。','前进直接接敌，侧翼机动以屏障阵形绕侧。舰体属性和奖励相同。','Maju mendekat langsung; sayap mendekat dari samping dengan formasi layar. Statistik dan hadiah sama.','Tiến thẳng áp sát; đánh sườn tiếp cận bên hông bằng đội hình chắn. Chỉ số và thưởng giữ nguyên.','เดินหน้าเข้าหาตรง ส่วนโอบข้างเข้าด้านข้างด้วยแนวคุ้มกัน ค่าสถานะและรางวัลเท่ากัน')+'</p><p class="cc-meta">'+tl('Win the real fleet battle. No permanent hull loss; damaged ships need repair.','실제 함대전에서 승리하세요. 함체 영구 손실은 없으며 손상 함선은 정비가 필요합니다.','実際の艦隊戦で勝利。永久損失なし、損傷艦は整備が必要です。','赢得实际舰队战。舰体无永久损失，受损舰船需要维修。','Menangkan pertempuran armada nyata. Lambung tidak hilang permanen; kapal rusak perlu diperbaiki.','Thắng trận hạm đội thật. Không mất thân tàu vĩnh viễn; tàu hỏng cần sửa.','ชนะการรบกองยานจริง ตัวเรือไม่สูญเสียถาวร เรือที่เสียหายต้องซ่อม')+'</p>';
  }
  function yieldNextAction(m,mine) {
    var complete=function(key){return (m.objectives||[]).some(function(o){return o.key===key&&o.complete;});};
    if((state.frontier.cargo||[]).some(function(c){return c.status==='moving'&&(!state.missions.starterFleet||String(c.fleet_id)===String(state.missions.starterFleet.fleetId));}))return button(L('화물 도착 확인','Check cargo arrival'),'check-cargo',null,'primary');
    if(!complete('production_collected')&&mine)return button(L('생산품 수령','Collect production'),'collect',mine.id,'primary');
    var stock=(state.frontier.stocks||[]).some(function(x){return x.depot==='mine'&&x.resource_code==='iron_dust'&&Number(x.quantity)>0;});
    return stock?button(L('정비 창고로 운송','Deliver to repair depot'),'cargo',null,'primary'):mine?button(L('생산품 수령','Collect production'),'collect',mine.id,'primary'):button(L('새로고침','Refresh'),'refresh');
  }
  function renderFront() {
    var f=state.frontier;if(!f)return '';var context=missionContext();var training=state.training;var missionId=context?.id;var running=context?.status==='active';
    var own=function(x){return x.owner_key===f.ownerKey;};
    var next=context||(!state.siegeContext&&state.missions&&(state.missions.missions||[]).find(function(m){return m.id===state.missions.currentMissionId&&m.status==='available';}));
    var mine=f.nodes.find(function(x){return x.node_type==='resource'&&own(x);});
    var iron=(f.stocks||[]).filter(function(x){return x.resource_code==='iron_dust';}).reduce(function(a,x){return a+Number(x.quantity||0);},0);
    var plates=(f.stocks||[]).filter(function(x){return x.resource_code==='hull_plate';}).reduce(function(a,x){return a+Number(x.quantity||0);},0);
    var html='<div class="cc-resource-bar"><div>'+icon('resources')+'<span>'+L('철 분말','Iron dust')+'</span><b>'+n(iron)+'</b></div><div>'+icon('cargo')+'<span>'+L('함체 판재','Hull plates')+'</span><b>'+n(plates)+'</b></div><div>'+icon('credits')+'<span>GP</span><b>'+(window.walletState&&window.walletState.gameGP!=null?n(window.walletState.gameGP):'—')+'</b></div></div>';
    if(!training&&(f.availableScopes||[]).indexOf('guild')!==-1)html+='<div class="cc-actions" aria-label="'+esc(L('전선 선택','Choose front'))+'">'+button(L('길드 공동 전선','Shared guild front'),'front-scope','guild',f.scope==='guild'?'primary':'')+button(L('개인 전선·창고','Personal front and depot'),'front-scope','personal',f.scope==='personal'?'primary':'')+'</div><p class="cc-meta">'+L('개인 재고와 길드 공동 재고는 분리되어 있습니다. 선택한 창고에서 생산·운송·정비합니다.','Personal and guild stock remain separate. Production, delivery and repair use the selected depot.')+'</p>';
    var goal=next?L.apply(null,missionLabels[missionIds.indexOf(next.id)]||[next.title,next.title]):L('내 함대가 지키는 생산선','A supply line your fleet protects');
    var goalAction=next?(next.status==='completed'?button(L('작전 보상 수령','Claim operation reward'),'claim-mission',next.id,'primary'):next.status==='available'?button(L('작전 시작','Start operation'),'start-mission',next.id,'primary'):next.id==='first_sortie'?button(L('출격 계속','Resume sortie'),'mission-action',next.id,'primary'):next.id==='move_yield'?yieldNextAction(next,mine):next.id==='restore_fleet'?button(L('작전 함선 정비','Repair operation ships'),'operation-repair',null,'primary')+button(L('정비 완료 점검','Inspect fleet readiness'),'inspect-fleet'):next.id==='secure_node'&&f.nodes.find(function(x){return x.node_type==='resource'&&!own(x);})?button(L('광산 거점 공략','Secure the mine'),'attack',f.nodes.find(function(x){return x.node_type==='resource';}).id,'primary'):next.id==='hold_front'&&mine?button(L('광산 방어 편성','Defend the mine'),'defense',mine.id,'primary'):''):button(L('함대 준비','Prepare fleet'),'tab','fleet','primary');
    html+='<section class="cc-hero cc-front-hero"><div class="cc-overline">'+L('다음 목표','NEXT OBJECTIVE')+'</div><h3>'+esc(goal)+'</h3><p>'+L('점령 → 생산 → 운송 → 수리. 다음 출격의 자원을 확보하세요.','Capture → produce → deliver → repair. Secure resources for your next sortie.')+'</p>'+(next&&next.id==='first_sortie'&&next.status==='available'?openingBrief():'')+'<div class="cc-actions">'+goalAction+'</div><div class="cc-production"><span>'+icon('resources')+L('생산','Production')+'</span><strong>'+(mine?(Number(mine.stored_batches)>0?L('수령 가능 · ','Ready · ')+n(mine.stored_batches)+L('회분',' batches'):L('다음 생산 ','Next batch ')+time(new Date(new Date(mine.production_at).getTime()+1800000))):L('광산을 확보하세요','Secure a mine'))+'</strong></div></section>';
    html+='<div class="cc-row between cc-section-heading"><h3>'+L('전선 거점','Frontier nodes')+'</h3><span class="cc-badge">'+(f.mode==='guild_front'?L('길드 전선','Guild front'):(training?L('개인 훈련','Training'):L('개인 전선','Personal front')))+'</span></div>';
    html+=fleetSelect();
    if(f.mode==='guild_front')html+='<p class="cc-meta">'+L('길드 전선에서는 출격 함체와 운송 화물을 잃을 수 있습니다.','Deployed hulls and cargo can be lost on the guild front.')+'</p>';
    html+='<div class="cc-node-map">'+f.nodes.map(function(x){var m=nodeMeta(x.node_type);return '<div class="cc-node '+(own(x)?'owned':'')+'"><div class="cc-node-icon">'+m[1]+'</div><strong>'+m[0]+'</strong><small>'+L(own(x)?'통제 중':x.owner_key?'상대 통제':'미점령',own(x)?'Controlled':x.owner_key?'Opponent':'Unclaimed')+'</small></div>';}).join('')+'</div><div class="cc-stack">';
    html+=f.nodes.map(function(x){var m=nodeMeta(x.node_type);return '<section class="cc-card '+(own(x)?'selected':'')+'"><div class="cc-row between"><h3>'+m[0]+'</h3><span class="cc-badge">'+esc(ko()?x.name:({resource:'Ares',logistics:'Phobos',repair:'Deimos'}[x.node_type]))+'</span></div><p>'+m[2]+'</p>'+(x.protected_until&&new Date(x.protected_until)>new Date()?'<p class="cc-meta">'+L('보호 종료 ','Protected until ')+time(x.protected_until)+'</p>':'')+(own(x)&&x.node_type==='resource'?'<p>'+L('저장 생산량 ','Stored batches ')+n(x.stored_batches)+' / '+n(batchCap())+' · '+L('다음 생산 ','Next batch ')+time(new Date(new Date(x.production_at).getTime()+1800000))+'</p>':'')+'<div class="cc-actions">'+(own(x)?(x.node_type==='resource'&&(!training||(running&&missionId==='move_yield'))?button(L('생산품 수령','Collect production'),'collect',x.id):'')+(!training||(running&&missionId==='hold_front')?button(L('선택 함대로 방어','Assign defense'),'defense',x.id):''):(!training||(running&&missionId==='secure_node'&&x.node_type==='resource')?button(L('거점 공략','Attack node'),'attack',x.id):'<span class="cc-meta">'+L('다음 작전에서 개방','Available in a later operation')+'</span>'))+'</div></section>';}).join('');
    html+='</div><section class="cc-card" style="margin-top:16px"><h3>'+L('전선 창고 · 실제 재고','Front depots · available materials')+'</h3><div class="cc-stock">'+['mine','repair'].map(function(d){return '<div>'+L(d==='mine'?'광산 창고':'정비 창고',d==='mine'?'Mine':'Repair depot')+f.stocks.filter(function(s){return s.depot===d;}).map(function(s){return '<b>'+n(s.quantity)+'</b>'+esc(resource(s.resource_code))+(!training&&d==='repair'&&f.canWithdrawStock!==false&&Number(s.quantity)>0?button(copy('제작 재료로 {amount}개 가져오기','Take {amount} for crafting',{amount:Math.min(100,Number(s.quantity))}),'withdraw-stock',d+'|'+s.resource_code):'');}).join('<br>')+'</div>';}).join('')+'</div><p class="cc-meta">'+L('광산 재료는 운송 후 정비·제작에 사용할 수 있습니다.','Mine materials become available for repair and crafting after delivery.')+'</p><div class="cc-row">'+(!training?'<div class="cc-field"><label for="ccCargoResource">'+L('운송 재료','Cargo material')+'</label><select id="ccCargoResource"><option value="iron_dust">'+resource('iron_dust')+'</option><option value="hull_plate">'+resource('hull_plate')+'</option></select></div>':'')+'<div class="cc-field"><label for="ccCargoAmount">'+L('운송량','Cargo amount')+'</label><input id="ccCargoAmount" type="number" value="20" min="1" max="'+cargoCapacity()+'" inputmode="numeric"></div>'+(!training||(running&&missionId==='move_yield')?button(L('정비 창고로 운송','Deliver to repair depot'),'cargo'):'')+'</div><p class="cc-meta">'+(training&&missionId==='move_yield'?L('첫 작전 운송은 1분입니다. 한 번에 최대 100개이며 도착까지 함대가 호위합니다.','First operation delivery takes 1 minute. Up to 100 units; the fleet escorts until arrival.'):copy('한 번에 최대 {capacity}개. 운송 중에는 해당 함대로 다른 출격을 할 수 없습니다.','Up to {capacity} per shipment. The escort fleet is occupied until arrival.',{capacity:cargoCapacity()}))+'</p><details><summary>'+L('운송 시간과 도착 확인','Delivery time and arrival check')+'</summary><p class="cc-meta">'+L('첫 작전은 1분, 일반 운송은 10분이며 물류 거점 통제 시 9분입니다. 앱을 닫아도 서버의 도착 시각은 유지됩니다. 돌아와 화물 도착 확인(작전) 또는 새로고침을 누르면 정비 창고에 반영됩니다. 창고 공간과 진행 중인 호위전을 확인하세요.','First operation: 1 minute. Normal delivery: 10 minutes, or 9 with logistics control. Arrival uses server timestamps even while the app is closed. Return and check cargo arrival (operation) or refresh to settle it into the repair depot. Check depot space and any ongoing escort battle.')+'</p></details></section>';
    if(f.canWithdrawStock===false)html+='<p class="cc-meta">'+L('개인 인출은 길드장·간부만 가능. 공동 수리·운송은 이용할 수 있습니다.','Only guild leaders and officers can withdraw to personal inventory. Shared repair and transport remain available.')+'</p>';
    var moving=(f.cargo||[]).filter(function(c){return c.status==='moving';});
    if(moving.length)html+='<section class="cc-card" style="margin-top:12px"><h3>'+L('운송 중','In transit')+'</h3>'+moving.map(function(c){return '<p>'+esc(resource(c.resource_code))+' × '+n(c.amount)+' · '+L('도착 ','Arrival ')+time(c.arrives_at)+' · '+esc(fleetName(c.fleet_id))+'</p><p class="cc-meta">'+(new Date(c.arrives_at)<=new Date()?L('도착 시각이 지났습니다. 상태를 확인해 정비 창고로 반영하세요.','Arrival time has passed. Check the state to settle delivery into the repair depot.'):L('앱을 닫아도 운송 시간은 흐릅니다. 호위 함대는 도착 정산까지 점유됩니다.','Delivery time continues with the app closed. The escort remains occupied until delivery settles.'))+'</p>'+button(L('도착 상태 확인','Check arrival state'),training&&missionId==='move_yield'?'check-cargo':'refresh')+button(L('출항 취소 · 1분 이내','Cancel · first minute'),'cancel-cargo',c.id);}).join('')+'</section>';
    var battles=f.battles||[];if(battles.length)html+='<details><summary>'+icon('chevron',16)+L('진행 중·최근 전투','Active and recent battles')+'</summary><div class="cc-stack">'+battles.slice(0,5).map(function(b){return button(L('전투 ','Battle ')+b.battle_id+' · '+(b.result||b.status),'battle',b.battle_id);}).join('')+'</div></details>';
    if(!training&&(f.raidTargets||[]).length)html+='<section class="cc-card" style="margin-top:12px"><h3>'+L('차단 가능한 적 화물','Enemy cargo to intercept')+'</h3><p>'+L('출항 후 20~90% 구간에만 차단 전투가 가능합니다.','Interception is available between 20% and 90% of the route.')+'</p><div class="cc-stack">'+f.raidTargets.map(function(c){return '<div><p>'+esc(resource(c.resource_code))+' × '+n(c.amount)+' · '+L('도착 ','Arrival ')+time(c.arrives_at)+'</p>'+button(L('선택 함대로 차단','Intercept with selected fleet'),'raid-cargo',c.id,'warn')+'</div>';}).join('')+'</div></section>';
    if(f.mode==='guild_front')html+='<section class="cc-card" style="margin-top:12px"><h3>'+L('길드 공동 목표','Shared guild objective')+'</h3><p>'+L('생산·운송·수리·방어를 동료와 나누어 완수하세요. 각자의 함대와 길드 공동 창고를 사용합니다.','Share production, delivery, repair and defense with your guild. Members use their own fleets and shared guild depots.')+'</p><p>'+L('시즌 거점 점수 ','Season hold points ')+n(f.score.hold_points)+' · '+L('운송 점수 ','Delivery points ')+n(f.score.delivery_points)+'</p><span class="cc-badge">'+(f.objective.complete?L('오늘 공동 목표 완료','Today’s objective complete'):L('공동 목표 진행 중','Objective in progress'))+'</span></section>';
    return html;
  }
  function renderFleet() {
    return '<section class="cc-hero"><div class="cc-overline">'+L('수집에서 출격까지','FROM COLLECTION TO SORTIE')+'</div><h3>'+L('함선은 모으고, 함대는 설계하세요','Collect ships. Build a fleet.')+'</h3><p>'+L('수집 도감은 격침 후에도 남습니다. 출격 함체는 수리·재건으로 복귀합니다.','Collection unlocks remain after destruction. Repair or rebuild your deployable hulls.')+'</p><div class="cc-actions">'+button(L('편성 관리','Manage fleet'),'legacy-fleet',null,'primary')+button(L('함선 카드·파츠','Ship cards / parts'),'cards')+button(L('도감·재건','Collection / rebuild'),'collection')+'</div></section><div class="cc-stack">'+(state.fleets.length?state.fleets.map(function(f){var pct=Math.min(100,Math.max(0,Number(f.total_hp)/Math.max(1,Number(f.total_max_hp))*100));return '<section class="cc-card"><div class="cc-row between"><h3>'+esc(f.name)+'</h3><span class="cc-badge">'+n(f.ships_alive)+L('척',' ships')+'</span></div><p>'+L('진형 ','Formation ')+esc(typeof _fcFormationName==='function'?_fcFormationName(f.formation):f.formation)+' · '+L('기동 ','Maneuver ')+esc(typeof _fcMovementName==='function'?_fcMovementName(f.movement):f.movement)+'</p><div class="cc-hp"><span style="width:'+pct+'%"></span></div><p class="cc-meta">HP '+n(f.total_hp)+' / '+n(f.total_max_hp)+'</p><div class="cc-actions">'+(f.current_battle_id?button(L('진행 중 전투 보기','Resume battle'),'battle',f.current_battle_id):button(L('출격 함대로 선택','Select for sortie'),'select-fleet',f.id))+button(L('함선·정비 보기','Ships / repair'),'fleet-detail',f.id)+'</div></section>';}).join(''):'<div class="cc-empty"><p>'+L('첫 작전에서 무료 시작 함대를 받으세요.','Get your starting fleet in the first operation.')+'</p>'+button(L('첫 작전 시작','First operation'),'tab','missions','primary')+'</div>')+'</div><div class="cc-actions">'+button(L('함선 영입·확률 확인','Recruit / view odds'),'gacha')+button(L('결투 초대·전투 기록','Duels / battle records'),'battle-hub')+button(L('목표형 작전 3종','Three objective operations'),'objectives')+button(L('전술 연습','Practice tactics'),'practice')+button(L('역할 가이드','Role guide'),'guide')+'</div>';
  }
  function renderMissions() {
    var s=state.missions; if(!s)return '';
    return '<section class="cc-hero"><div class="cc-overline">'+L('첫 전선 · 5개 작전','FIRST FRONT · FIVE OPERATIONS')+'</div><h3>'+L('지휘관이 되는 다섯 번의 선택','Five steps to command')+'</h3><p>'+L('실제 전투와 생산 기록으로 진행됩니다. 첫 출격에는 가챠가 필요하지 않습니다.','Progress follows real battles and industry. No crate draw is needed for your first sortie.')+'</p><p class="cc-meta">'+tl('Each completed operation grants 5 iron dust to the repair depot once. Mine production must be collected and delivered before it can repair your fleet.','작전마다 철 분말 5개를 정비 창고에 한 번 받습니다. 광산 생산품은 수령하고 운송해야 함대 정비에 쓸 수 있습니다.','各作戦で鉄粉5を整備倉庫に1回支給。鉱山生産品は回収・輸送後に艦隊整備に使えます。','每项行动完成后一次性向维修仓库发放5铁尘。矿山产出须收取并运输后才能维修舰队。','Setiap operasi memberi 5 debu besi ke depot perbaikan satu kali. Hasil tambang harus diambil dan dikirim untuk memperbaiki armada.','Mỗi chiến dịch cấp 5 bụi sắt vào kho sửa chữa một lần. Phải thu và vận chuyển sản lượng mỏ để sửa hạm đội.','แต่ละปฏิบัติการให้ฝุ่นเหล็ก 5 หน่วยเข้าคลังซ่อมครั้งเดียว ต้องเก็บและขนผลผลิตจากเหมืองก่อนใช้ซ่อมกองยาน')+'</p></section><div class="cc-stack">'+(s.missions||[]).map(function(m,i){var active=m.status==='active',done=['completed','claimed'].includes(m.status);return '<section class="cc-card '+(active?'selected':'')+'"><div class="cc-step"><span class="cc-step-num">'+(done?icon('check',18):i+1)+'</span><div><h3>'+esc(L.apply(null,missionLabels[i]||[m.title,m.title]))+'</h3><span class="cc-badge">'+({locked:L('준비 중','Locked'),available:L('시작 가능','Ready'),active:L('진행 중','Active'),completed:L('보상 수령 가능','Ready to claim'),claimed:L('완료','Complete')}[m.status]||esc(m.status))+'</span>'+(m.objectives||[]).map(function(o){return '<p style="margin-top:8px"><span class="cc-objective-status">'+icon(o.complete?'check':'pending',16)+'<span class="game-sr-only">'+L(o.complete?'완료: ':'진행 중: ',o.complete?'Complete: ':'In progress: ')+'</span></span>'+esc(({battle_won:L('실제 함대전 승리','Win a fleet battle'),node_captured:L('자원 거점 점령','Capture the resource node'),production_collected:L('거점 생산 인수','Collect node production'),cargo_arrived:L('화물 도착','Deliver the cargo'),fleet_ready:L('전력 정비 또는 점검','Repair or inspect the fleet'),node_defended:L('방어 편성 저장','Save the defense formation')})[o.key]||o.label)+' <small>'+n(o.current)+' / '+n(o.target)+'</small></p>';}).join('')+(m.id==='first_sortie'&&m.status==='available'?openingBrief():'')+'<div class="cc-actions">'+(m.status==='completed'?button(L('보상 수령','Claim reward'),'claim-mission',m.id,'primary'):m.status==='claimed'?'':active?button(L('작전 계속','Continue operation'),'mission-action',m.id,'primary'):s.currentMissionId===m.id?button(L('작전 시작','Start operation'),'start-mission',m.id,'primary'):'<p class="cc-meta">'+L('앞선 작전을 완료하면 열립니다.','Complete the previous operation to unlock.')+'</p>')+'</div></div></div></section>';}).join('')+'</div><div class="cc-actions">'+button(L('이야기 캠페인','Story campaign'),'story')+button(L('전선으로','Go to front'),'tab','front')+'</div>';
  }
  function renderBase() {
    var language='<div class="cc-field"><label for="ccLanguage">'+L('언어','Language')+'</label><select id="ccLanguage">'+[['en','English'],['ko','한국어'],['ja','日本語'],['zh','中文'],['id','Indonesia'],['vi','Tiếng Việt'],['th','ไทย']].map(function(x){return '<option value="'+x[0]+'"'+(typeof LANG!=='undefined'&&LANG===x[0]?' selected':'')+'>'+x[1]+'</option>';}).join('')+'</select></div>';
    return language+ '<section class="cc-hero"><div class="cc-overline">'+L('다음 출격을 준비하는 곳','PREPARE THE NEXT SORTIE')+'</div><h3>'+L('기지와 전선은 이어집니다','Your base supports the front')+'</h3><p>'+L('전방 재고를 운송하고 손상 함선을 고쳐 다시 출격하세요. 영구 도감과 기존 토지는 계속 보유합니다.','Deliver front-line materials, repair damage, and launch again. Your collection and existing land remain yours.')+'</p></section><div class="cc-grid"><section class="cc-card"><h3>'+L('내 영토','My territory')+'</h3><p>'+L('기존 토지의 생산과 건물을 관리합니다.','Manage production and buildings on your land.')+'</p>'+button(L('영토 보기','View territory'),'land')+'</section><section class="cc-card"><h3>'+L('기지 관리','Base management')+'</h3><p>'+L('자원·건조·길드·보유 아이템을 관리합니다.','Manage resources, construction, guild and inventory.')+'</p>'+button(L('기지 관리 열기','Open management'),'legacy-base')+'</section><section class="cc-card"><h3>'+L('함선 수리·재건','Repair and rebuild')+'</h3><p>'+L('살아남은 함선은 정비하고, 격침 함체는 도감에서 재건하세요.','Repair surviving ships or rebuild lost hulls from your collection.')+'</p>'+button(L('함대로 이동','Go to fleet'),'tab','fleet')+'</section><section class="cc-card"><h3>'+L('토지 확보','Claim land')+'</h3><p>'+L('빈 토지를 확보합니다. 적 소유 토지는 함대전이 필요합니다.','Claim empty land. Enemy land requires fleet combat.')+'</p>'+button(L('지도에서 선택','Choose on map'),'claim-land')+'</section></div>';
  }
  async function load() {
    if(!localStorage.getItem('pw_token')){open(state.tab);return;}
    var request=++state.request;toast('');setBody(function(){return '<p role="status">'+L('작전 정보를 불러오는 중…','Loading operation state…')+'</p>';});
    try {
      if(state.tab==='front'){var r=await Promise.all([api('/fleets'),state.siegeContext?Promise.resolve(null):api('/starter-ops/state')]);if(request!==state.request)return;state.fleets=r[0].fleets||[];state.missions=r[1];state.training=!!missionContext();state.frontier=await api(state.training?'/starter-ops/frontier-state':'/frontier/state');if(request!==state.request)return;if(missionContext()&&state.missions.starterFleet)state.fleetId=String(state.missions.starterFleet.fleetId);}
      else if(state.tab==='fleet'){var f=await api('/fleets');if(request!==state.request)return;state.fleets=f.fleets||[];if(state.siegeContext){state.frontier=await api('/frontier/state');if(request!==state.request)return;}}
      else if(state.tab==='missions'){var m=await api('/starter-ops/state');if(request!==state.request)return;state.missions=m;}
      if(request!==state.request||root.hidden)return;
      if(state.siegeContext&&!state.fleets.some(function(f){return String(f.id)===state.fleetId;}))state.fleetId='';
      if(!state.fleetId&&state.fleets.length)state.fleetId=String(state.fleets.find(function(f){return Number(f.ships_alive)>0&&!f.is_in_battle;})?.id||'');
      setBody({front:renderFront,fleet:renderFleet,missions:renderMissions,base:renderBase}[state.tab]);
    }catch(e){if(request!==state.request)return;setBody(function(){return '<div class="cc-empty"><p>'+esc(errorText(e))+'</p>'+button(L('다시 불러오기','Retry'),'refresh')+'</div>';});}
  }
  function open(tab,context) {
    if(!root)return;++state.request;state.tab=titles[tab]?tab:'front';
    var nextContext=siegeContext(context);
    if((nextContext||state.siegeContext)&&context!==state.siegeContext){state.frontierScope='';state.frontier=null;state.fleets=[];state.fleetId=nextContext&&nextContext.ownFleetId?String(nextContext.ownFleetId):'';}
    state.siegeContext=nextContext;
    if(nextContext){state.missions=null;state.training=false;}
    if(typeof closeBaseModal==='function')closeBaseModal();
    previousFocus=document.activeElement;root.hidden=false;document.body.classList.add('command-center-open');
    document.querySelectorAll('[data-command-nav]').forEach(function(b){b.setAttribute('aria-current',b.dataset.commandNav===state.tab?'page':'false');var label=b.querySelector('[data-command-label]')||b.querySelector('span:not([data-game-icon])');if(label)label.textContent=L.apply(null,titles[b.dataset.commandNav]);});
    root.querySelector('h2').textContent=L.apply(null,titles[state.tab]);var mapButton=root.querySelector('[data-cc="close"]');mapButton.setAttribute('aria-label',L('영토 지도 보기','View territory map'));mapButton.title=L('영토 지도 보기','View territory map');mapButton.innerHTML=icon('territory',20);root.querySelector('[data-cc="refresh"]').setAttribute('aria-label',L('새로고침','Refresh'));var chat=document.getElementById('chatOverlay');if(chat)root.querySelector('.cc-header').insertBefore(chat,mapButton);mapButton.focus();
    if(!localStorage.getItem('pw_token')){setBody(function(){return '<section class="cc-hero"><h3>'+L('당신의 첫 함대가 기다립니다','Your first fleet awaits')+'</h3><p>'+L('로그인하고 무료 시작 함대로 첫 전투를 경험하세요.','Sign in and experience combat with a free starting fleet.')+'</p>'+button(L('로그인·가입','Sign in / join'),'login',null,'primary')+'</section>';});return;}
    if(typeof trackProductEvent==='function')trackProductEvent('ui_view',{view:'command/'+state.tab});load();
  }
  function close() { if(!root)return;root.hidden=true;++state.request;document.body.classList.remove('command-center-open');var chat=document.getElementById('chatOverlay');if(chat){if(!chat.classList.contains('collapsed'))window.toggleCommandChat();document.body.appendChild(chat);}if(previousFocus&&previousFocus.isConnected)previousFocus.focus(); }
  async function confirmRisk(title,bodyText) { return typeof gameConfirm==='function'&&await gameConfirm({title:title,body:esc(bodyText),confirmText:L('확인하고 진행','Confirm and continue')}); }
  async function viewBattle(id) { close();if(typeof openBattleViewer==='function')await openBattleViewer(id); }
  async function detail(id) {
    var req=++state.request;var data=await api('/fleets/'+encodeURIComponent(id)),f=data.fleet||data;if(req!==state.request||root.hidden)return;
    setBody(function(){return '<div class="cc-actions">'+button(L('함대 목록','Fleet list'),'tab','fleet')+'</div><h3 style="margin-top:16px">'+esc(f.name)+'</h3><div class="cc-stack">'+(f.ships||[]).map(function(s){return '<article class="cc-card"><div class="cc-row"><img class="cc-ship" loading="lazy" src="/assets/ships/top/'+encodeURIComponent(s.ship_type_code)+'.png" alt=""><div><h4>'+esc(typeof syShipName==='function'?syShipName(s):(ko()?s.name_ko||s.name_en||s.ship_type_code:s.name_en||s.ship_type_code))+'</h4><p class="cc-meta">'+esc(role(s.role))+' · HP '+n(s.current_hp)+' / '+n(Number(s.max_hp)+Number(s.bonus_hp||0))+'</p></div></div>'+(!state.siegeContext||s.is_alive!==false&&Number(s.current_hp)>0&&Number(s.current_hp)<Number(s.max_hp)+Number(s.bonus_hp||0)?button(L('정비 비용 확인','Review repair cost'),'repair-quote',s.id):s.is_alive===false||Number(s.current_hp)<=0?button(L('도감·재건','Collection / rebuild'),'collection'):'')+'</article>';}).join('')+'</div>';});
    body.scrollTop=0;
  }
  async function action(a,id) {
    if(a==='close'){close();return;}if(a==='tab'){open(id,id==='missions'?null:state.siegeContext);return;}if(a==='refresh'){await load();return;}
    if(a==='siege-supply'){open('front',state.siegeContext);return;}
    if(a==='siege-repair'){if(state.fleetId){await detail(state.fleetId);return;}open('fleet',state.siegeContext);return;}
    if(a==='siege-return'){var context=state.siegeContext;close();if(context&&typeof window.loadSiegeInfoPanel==='function')window.loadSiegeInfoPanel(context.sectorCode);return;}
    if(a==='front-scope'){state.frontierScope=id==='personal'?'personal':'';await load();return;}
    if(a==='faction'){close();if(typeof loadFactions==='function')await loadFactions();if(typeof openFactionModal==='function')openFactionModal();return;}
    if(a==='login'){close();if(typeof openAuthModal==='function')openAuthModal();return;}
    var legacy={faction:'openFactionModal','legacy-fleet':'openFleetCmd',collection:'openShipyard',cards:'openShipCardWorkshop',guide:'openFleetFieldGuide',objectives:'openObjectiveOperations',gacha:'openGacha','battle-hub':'openBattleHub',practice:'openTacticalLab',story:'openCampaignHub','legacy-base':'openBaseModal',land:'toggleMyLand','claim-land':'activateLandSelect'};
    if(legacy[a]){close();if(typeof window[legacy[a]]==='function'){if(a==='faction'&&typeof loadFactions==='function')await loadFactions();await window[legacy[a]]();if(a==='collection'&&typeof switchSyTab==='function')switchSyTab('fleet');}return;}
    if(a==='battle'){await viewBattle(id);return;}if(a==='fleet-detail'){await detail(id);return;}
    if(a==='select-fleet'){state.fleetId=String(id);if(state.siegeContext)state.siegeContext.ownFleetId=Number(id);open('front',state.siegeContext);return;}
    var result;
    if(a==='attack'||a==='defense'){
      var fleetId=selectedFleet();var risk=state.frontier.mode==='guild_front';
      if(risk&&!await confirmRisk(L('길드 전선 출격','Deploy to the guild front'),L('선택한 함대는 전방 전투에 참여합니다. 영구 손실 모드에서 양측 모두 영구 손실에 동의한 경우에만 함체가 소실됩니다. 그 외에는 HP 15%로 복귀합니다. 방어 편성은 부재 중에도 공격받을 수 있습니다. 수집 도감은 유지됩니다.','The selected fleet enters front-line combat. Hulls are permanently lost only when permanent loss mode is enabled and both players opt in. Otherwise, defeated hulls return at 15% HP. Assigned defenders can be attacked while you are away. Collection unlocks remain.')))return;
      result=await operationAction(a==='attack'?'secure_node':'hold_front',a==='attack'?'attack_node':'save_defense',a==='attack'?'/frontier/nodes/'+id+'/attack':'/frontier/defense',a==='attack'?{fleetId:fleetId,nodeId:id,riskConsent:risk}:{nodeId:id,fleetId:fleetId,riskConsent:risk});
      if(result.battleId){await viewBattle(result.battleId);return;}
    }else if(a==='raid-cargo'){var attacker=selectedFleet();if(!await confirmRisk(L('화물 차단 전투','Intercept enemy cargo'),L('선택 함대가 실제 운송 호위함대와 싸웁니다. 승리하면 화물의 50%를 회수합니다. 영구 손실 모드에서 양측 모두 동의한 경우에만 함체가 소실되며, 그 외에는 HP 15%로 복귀합니다.','Your fleet fights the actual cargo escort. Victory recovers 50% of the cargo. Permanent hull loss requires an enabled permanent loss mode and both players opting in; otherwise defeated hulls return at 15% HP.')))return;result=await api('/frontier/cargo/'+id+'/attack',{fleetId:attacker,riskConsent:true});if(result.battleId){await viewBattle(result.battleId);return;}}else if(a==='collect')result=await operationAction('move_yield','collect_production','/frontier/production/collect',{nodeId:id});
    else if(a==='cargo'){
      var amount=Number(document.getElementById('ccCargoAmount').value),fleet=selectedFleet(),cargoResource=document.getElementById('ccCargoResource')?.value||'iron_dust';
      if(['iron_dust','hull_plate'].indexOf(cargoResource)===-1)throw Error('INVALID_RESOURCE');
      if(!Number.isInteger(amount)||amount<1||amount>cargoCapacity())throw Error(copy('운송량은 1~{capacity}개입니다.','Choose 1–{capacity} units.',{capacity:cargoCapacity()}));
      var minutes=cargoMinutes(),deliveryBrief=fleetName(fleet)+' · '+resource(cargoResource)+' × '+n(amount)+' · '+L('예상 ','Estimated ')+minutes+L('분 · 도착 ',' min · arrival ')+time(new Date(Date.now()+minutes*60000))+'. '+L('도착 정산까지 이 함대는 다른 출격에 사용할 수 없습니다. 앱을 닫아도 운송 시간은 흐르며, 돌아와 도착 상태를 확인하세요.','This fleet is occupied until delivery settles. Time continues with the app closed; return to check arrival.');
      if(state.frontier.mode==='guild_front')deliveryBrief+=' '+L('선택한 함대가 실제 호위전에 참여합니다. 패배하면 화물의 50%를 잃습니다. 영구 손실 모드에서 양측 모두 동의한 경우에만 함체가 소실되며, 그 외에는 HP 15%로 복귀합니다.','Your selected fleet fights to defend the cargo. Defeat loses 50% of the cargo. Permanent hull loss requires an enabled permanent loss mode and both players opting in; otherwise defeated hulls return at 15% HP.');
      if(!await confirmRisk(L('화물 운송','Cargo delivery'),deliveryBrief))return;
      result=await operationAction('move_yield','start_cargo','/frontier/cargo',{fleetId:fleet,amount:amount,resourceCode:cargoResource});
    }else if(a==='withdraw-stock'){
      var stockKey=String(id).split('|'),stockItem=(state.frontier.stocks||[]).find(function(s){return s.depot===stockKey[0]&&s.resource_code===stockKey[1];});if(!stockItem)throw Error('INSUFFICIENT_STOCK');var take=Math.min(100,Number(stockItem.quantity));
      if(!await confirmRisk(L('제작 재료로 이전','Transfer crafting materials'),L('전선 창고에서 내 보유 재료로 가져옵니다. ','Move materials from the front depot to your inventory. ')+resource(stockKey[1])+' × '+n(take)+(state.frontier.mode==='guild_front'?L(' 길드 공동 재고가 줄어듭니다.',' This reduces shared guild stock.'):'')))return;
      result=await api('/frontier/stock/withdraw',{depot:stockKey[0],resourceCode:stockKey[1],amount:take});
    }else if(a==='cancel-cargo')result=await api('/frontier/cargo/'+id+'/cancel',{});
    else if(a==='start-mission'||a==='claim-mission'){
      result=await api('/starter-ops/'+id+(a==='start-mission'?'/start':'/claim'),a==='start-mission'&&id==='first_sortie'?{openingTactic:state.openingTactic}:{});
      var battleId=result.battleId||result.battle?.battleId;if(battleId){await viewBattle(battleId);return;}if(a==='claim-mission'){open('missions');return;}if(a==='start-mission'&&id!=='first_sortie'){open('front');return;}
    }else if(a==='mission-action'){
      // Mission-specific actions are selected on the operation panel, never supplied as evidence IDs.
      if(id==='first_sortie'){result=await api('/starter-ops/'+id+'/start',{});var bid=result.battleId||result.battle?.battleId;if(bid){await viewBattle(bid);return;}}
      else{open('front');return;}
    }else if(a==='check-cargo'){result=await api('/starter-ops/move_yield/action',{action:'check_cargo'});
    }else if(a==='inspect-fleet'){result=await api('/starter-ops/restore_fleet/action',{action:'inspect_fleet'});
    }else if(a==='operation-repair'){if(state.missions?.starterFleet){await detail(state.missions.starterFleet.fleetId);return;}
    }else if(a==='repair-quote'){
      var response=await api((activeMission()?.id==='restore_fleet'?'/starter-ops':'/frontier')+'/repair-quote?shipId='+encodeURIComponent(id)+'&targetHpPct=100');var quote=response.quote||response;
      if(!await confirmRisk(L('전선 정비','Front repair'),(quote.tutorial_subsidy?L('첫 정비 지원 · 계정당 1회. ','First repair subsidy · once per account. '):'')+L('정비 창고의 철 분말 ','Repair depot iron dust ')+n(quote.iron_used)+' · '+n(quote.gp_cost)+' GP → HP '+n(quote.target_hp)))return;
      result=await operationAction('restore_fleet','repair_ship','/frontier/repair',{shipId:id,targetHpPct:100,expectedQuote:quote});
    }
    if(result){await load();toast(L('서버에 반영했습니다.','Saved on the server.'));}
  }
  window.toggleCommandChat=function(){
    if(typeof window.toggleChat!=='function')return;
    window.toggleChat();
    var overlay=document.getElementById('chatOverlay'),control=document.getElementById('chatToggleBtn');
    var expanded=overlay&&!overlay.classList.contains('collapsed');
    if(control){control.setAttribute('aria-expanded',String(expanded));control.setAttribute('aria-label',L(expanded?'통신 닫기':'통신 열기',expanded?'Close communications':'Open communications'));}
    if(expanded){var input=document.getElementById('chatInput');if(input)input.focus();}
  };
  function init() {
    window.refreshCommandCenterLocale();
    root=document.getElementById('commandCenter');if(!root)return;body=root.querySelector('.cc-body');status=root.querySelector('.cc-status');
    ['refresh','close'].forEach(function(name){var control=root.querySelector('[data-cc="'+name+'"]');if(control&&window.GameIcons)control.innerHTML=icon(name,20);});
    document.querySelectorAll('[data-command-nav]').forEach(function(b){var label=b.querySelector('[data-command-label]')||b.querySelector('span:not([data-game-icon])');if(label)label.textContent=L.apply(null,titles[b.dataset.commandNav]);b.addEventListener('click',function(){open(b.dataset.commandNav);});});
    root.addEventListener('click',async function(e){var b=e.target.closest('[data-cc]');if(!b||state.busy)return;state.busy=true;b.disabled=true;try{await action(b.dataset.cc,b.dataset.id);}catch(err){if(err.message==='STALE_REQUEST')return;toast(errorText(err),true);if(err.message==='FACTION_REQUIRED')body.insertAdjacentHTML('afterbegin','<section class="cc-card selected"><p>'+L('첫 함대의 진영을 선택하세요.','Choose a faction for your first fleet.')+'</p>'+button(L('진영 선택','Choose faction'),'faction',null,'primary')+'</section>');}finally{state.busy=false;if(b.isConnected)b.disabled=false;}});
    root.addEventListener('change',function(e){if(e.target.id==='ccOpeningTactic')state.openingTactic=e.target.value;if(e.target.id==='ccFleetSelect'){state.fleetId=e.target.value;if(state.siegeContext){state.siegeContext.ownFleetId=Number(e.target.value)||null;var label=document.getElementById('ccSiegeFleetName'),fleet=state.fleets.find(function(f){return String(f.id)===state.fleetId;});if(label)label.textContent=fleet?fleet.name+' · HP '+n(fleet.total_hp)+' / '+n(fleet.total_max_hp):L('함대 선택','Select a fleet');}}if(e.target.id==='ccLanguage'&&typeof setLang==='function'){setLang(e.target.value);}});
    document.addEventListener('keydown',function(e){if(root.hidden)return;if(e.key==='Escape'&&document.getElementById('chatOverlay')&&!document.getElementById('chatOverlay').classList.contains('collapsed')){window.toggleCommandChat();document.getElementById('chatToggleBtn').focus();e.stopPropagation();return;}if(e.key==='Escape'&&!document.getElementById('gameConfirm')?.classList.contains('open')){close();e.stopPropagation();}});
    document.addEventListener('visibilitychange',function(){if(!document.hidden&&!root.hidden&&!state.busy)load();});
    window.addEventListener('online',function(){if(!root.hidden&&!state.busy)load();});
    // Keep Mars and its painted menu as home; the command panel opens only on request.
    document.addEventListener('click',function(e){
      if(!root.hidden&&e.target.closest('.mob-nav-item,.col-fab'))close();
    },true);

  }
  window.openCommandCenter=open;window.closeCommandCenter=close;
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init);else init();
}());
